"""Build only curated synthetic public material; never reads runtime evidence or credentials.
Authoring-only dependencies: reportlab. Run with the Codex bundled authoring Python.
"""
from pathlib import Path
import json, hashlib, html
from xml.sax.saxutils import escape
from reportlab.platypus import SimpleDocTemplate, Paragraph, Spacer, PageBreak, KeepTogether
from reportlab.lib.styles import getSampleStyleSheet, ParagraphStyle
from reportlab.lib.colors import HexColor
from reportlab.lib.enums import TA_LEFT
from reportlab.lib.pagesizes import A4

ROOT=Path(__file__).resolve().parents[1]
OUT=ROOT/'site'
REL=json.loads((ROOT/'backend/app/release.json').read_text())
GUIDES=json.loads((ROOT/'docs/guides/catalogue.json').read_text())
VERSION=REL['version']
PDF=OUT/'documentation'/'files';PDF.mkdir(parents=True,exist_ok=True)
styles=getSampleStyleSheet()
styles.add(ParagraphStyle(name='GuideTitle',fontName='Helvetica-Bold',fontSize=27,leading=33,textColor=HexColor('#17334f'),spaceAfter=20))
styles.add(ParagraphStyle(name='GuideHeading',fontName='Helvetica-Bold',fontSize=19,leading=25,textColor=HexColor('#17334f'),spaceAfter=18))
styles.add(ParagraphStyle(name='GuideBody',fontName='Helvetica',fontSize=11,leading=17,spaceAfter=17,textColor=HexColor('#26374a')))
styles.add(ParagraphStyle(name='GuideMeta',fontName='Helvetica',fontSize=10,leading=15,textColor=HexColor('#4c6176'),spaceAfter=12))

def footer(canvas,doc):
 canvas.setTitle(doc.title);canvas.setAuthor('Cluster Assurance Orchestrator project')
 canvas.setStrokeColor(HexColor('#dce3eb'));canvas.line(48,44,A4[0]-48,44)
 canvas.setFont('Helvetica',8);canvas.setFillColor(HexColor('#4c6176'))
 canvas.drawString(48,30,f'Cluster Assurance | {VERSION} | Synthetic examples only')
 canvas.drawRightString(A4[0]-48,30,str(doc.page))

for guide in GUIDES:
 name=f"CAO-{guide['id']}-{VERSION}.pdf"
 guide['pdf']='files/'+name
 story=[Spacer(1,38),Paragraph('OPERATIONS DOCUMENTATION',styles['GuideMeta']),Paragraph(escape(guide['title']),styles['GuideTitle']),Paragraph(escape(guide['summary']),styles['GuideBody']),Paragraph(f"Version {VERSION} | Production-test candidate<br/>Audience: {escape(guide['audience'])}",styles['GuideMeta']),Spacer(1,22),Paragraph('Evidence boundary',styles['GuideHeading']),Paragraph('Source-reviewed guidance. No production acceptance is implied. Examples are synthetic and contain no collected PE/PC data. This independent project is not affiliated with or supported by Nutanix.',styles['GuideBody']),Paragraph('How to use this guide',styles['GuideHeading']),Paragraph('Follow the checks in order. Preserve unknown results and verify installed-release applicability. Infrastructure corrections require a separate authorised change and rollback plan.',styles['GuideBody'])]
 for sec in guide['sections']:
  story += [PageBreak(),Paragraph(escape(sec['title']),styles['GuideHeading'])]
  for index,step in enumerate(sec['steps'],1):story.append(Paragraph(f'<b>{index:02d}</b>  '+escape(step),styles['GuideBody']))
 story += [Spacer(1,12),Paragraph('Source basis: '+escape(', '.join(guide['source'])),styles['GuideMeta'])]
 doc=SimpleDocTemplate(str(PDF/name),pagesize=A4,rightMargin=48,leftMargin=48,topMargin=48,bottomMargin=60,title=guide['title'], invariant=1)
 doc.build(story,onFirstPage=footer,onLaterPages=footer)
 guide['sha256']=hashlib.sha256((PDF/name).read_bytes()).hexdigest()
 # Human-editable companion, sourced from the same content as the PDF.
 md='# '+guide['title']+'\n\n'+guide['summary']+f'\n\nVersion: {VERSION}. All examples are synthetic.\n'
 for sec in guide['sections']:md+='\n## '+sec['title']+'\n\n'+'\n\n'.join(f'{i}. {v}' for i,v in enumerate(sec['steps'],1))+'\n'
 md+='\nSource basis: '+', '.join(guide['source'])+'\n'
 (ROOT/'docs/guides'/f"{guide['id']}.md").write_text(md,encoding='utf-8')

(OUT/'documentation'/'library.json').write_text(json.dumps({'version':VERSION,'classification':'synthetic-public-documentation','guides':GUIDES},indent=2)+'\n')
(PDF/'SHA256SUMS').write_text('\n'.join(g['sha256']+'  '+Path(g['pdf']).name for g in GUIDES)+'\n')

def page(title,body,depth=0,script=''):
 prefix='../'*depth
 return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{title} | Cluster Assurance</title><link rel="stylesheet" href="{prefix}styles.css"></head><body><a class="skip" href="#main">Skip to content</a><header><a class="brand" href="{prefix}index.html">CA<span>Cluster Assurance<small>Operations confidence, grounded in evidence</small></span></a><nav aria-label="Resources"><a href="{prefix}index.html#status">Release status</a><a href="{prefix}demo/">Interactive demo</a><a href="{prefix}tutorials/">Tutorials</a><a href="{prefix}documentation/">PDF library</a><a href="https://github.com/VirtuArchitect/Cluster-Assurance-Orchestrator">Repository</a></nav></header><main id="main">{body}</main><footer>Independent project. Not affiliated with, endorsed by or supported by Nutanix. Nutanix product names are trademarks of their owners.<br/>Public examples are synthetic. Production acceptance requires an approved test record. <a href="{prefix}documentation/">Documentation</a></footer>{script}</body></html>'''

(OUT/'styles.css').write_text('''*{box-sizing:border-box}body{margin:0;background:#f3f5f8;color:#17334f;font:16px/1.6 system-ui,sans-serif}a{color:#1256a2;text-underline-offset:4px}a:hover{color:#087c91}header{background:#202020;color:white;padding:24px max(5vw,20px);display:flex;gap:28px;align-items:center;justify-content:space-between}header a{color:#e6e6e6;text-decoration:none}nav{display:flex;gap:22px;flex-wrap:wrap;font-size:14px}.brand{font-size:24px;font-weight:750;display:flex;gap:14px;align-items:center}.brand span{font-size:18px}.brand small{display:block;font-size:11px;font-weight:400;color:#bdbdbd}main{max-width:1240px;margin:auto;padding:48px 28px}h1{font-size:clamp(32px,4vw,52px);line-height:1.14;max-width:820px;letter-spacing:-.03em;margin:12px 0 24px}h2{font-size:26px;line-height:1.3}h3{line-height:1.35}p{max-width:850px}.eyebrow{font-size:12px;font-weight:700;letter-spacing:.13em;text-transform:uppercase;color:#087c91}.lead{font-size:20px;color:#425b73}.actions{display:flex;gap:12px;flex-wrap:wrap;margin:28px 0}.button{display:inline-flex;background:#1558aa;color:white;padding:10px 17px;border-radius:5px;text-decoration:none;border:1px solid #1558aa;font:inherit;cursor:pointer}.button:hover{color:white;background:#12488a}.secondary{background:white;color:#1558aa;border-color:#c3cfdb}.secondary:hover{background:#e8edf4;color:#12488a}.grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:20px}.card{padding:24px;background:white;border:1px solid #dbe2ea;border-radius:8px}.card h3{margin:0 0 12px}.card p{font-size:15px;color:#425b73}.card .button{font-size:14px}.notice{padding:20px 24px;background:#fff;border:1px solid #dbe2ea;border-left:4px solid #ad7513;border-radius:5px;margin:24px 0}.meta{font-size:13px;color:#536a7e}.badge{display:inline-block;background:#fff1cd;color:#6c4805;border:1px solid #dcc487;padding:3px 9px;border-radius:4px;font-size:12px;font-weight:650}section{margin:48px 0}footer{border-top:1px solid #dbe2ea;padding:28px max(5vw,20px);font-size:12px;color:#536a7e}.skip{position:absolute;top:-100px}.skip:focus{top:0;background:white;padding:12px;z-index:9}:focus-visible{outline:3px solid #087c91;outline-offset:4px}input,select{font:inherit;padding:10px;border:1px solid #9aafc1;border-radius:4px;max-width:100%}.search{display:grid;gap:6px;margin:24px 0}.search input{width:100%}.reader{background:white;padding:28px;border:1px solid #dbe2ea;border-radius:8px;margin:24px 0}.reader li{padding:0 0 18px}.step{font-size:18px}.steps-nav{display:flex;gap:12px;align-items:center;flex-wrap:wrap}button:disabled{opacity:.45;cursor:default}.hash{overflow-wrap:anywhere;font:11px/1.6 ui-monospace,monospace}.flow{display:grid;grid-template-columns:repeat(4,1fr);gap:14px;margin:32px 0}.flow div{background:#fff;border:1px solid #dbe2ea;border-top:3px solid #087c91;border-radius:6px;padding:18px}.flow strong{display:block}.flow small{font-size:13px}iframe{width:100%;height:700px;border:1px solid #dbe2ea}video{width:100%;background:#202020;border-radius:7px}.hidden{display:none!important}@media(max-width:900px){header{align-items:flex-start;flex-direction:column}.grid{grid-template-columns:repeat(2,1fr)}.flow{grid-template-columns:repeat(2,1fr)}}@media(max-width:600px){main{padding:30px 18px}.grid,.flow{grid-template-columns:1fr}h1{font-size:34px}nav{gap:14px}.reader{padding:18px}iframe{height:500px}}''')

cards=''.join(f'<article class="card"><h3>{html.escape(g["title"])}</h3><p>{html.escape(g["summary"])}</p><a href="documentation/?doc={g["id"]}">Read guide and download PDF</a></article>' for g in GUIDES[:3])
(OUT/'index.html').write_text(page('Project and release resources',f'''<span class="eyebrow">Read-only operational support for Nutanix environments</span><h1>Know what needs attention.<br/>Understand what the evidence proves.</h1><p class="lead">A PE and PC operations console that separates source alerts, collection confidence and recovery follow-ups, with practical triage for the next action.</p><div class="actions"><a class="button" href="demo/">Explore the synthetic demo</a><a class="button secondary" href="tutorials/">Start a tutorial</a><a class="button secondary" href="documentation/">Browse PDF documentation</a></div><section id="status"><span class="badge">{VERSION} · production-test candidate</span><h2>Testable does not mean production approved</h2><p>Release identity, build revision and source state are visible in Settings &gt; About and the health API. A reviewed immutable package, successful validation and an explicit acceptance decision remain separate requirements.</p><div class="notice">This site describes the candidate source. It is not a live health view, a published appliance release, or evidence of successful production testing. Download approved packages only after reviewing the repository release record.</div><a href="https://github.com/VirtuArchitect/Cluster-Assurance-Orchestrator/releases">Review release records</a> · <a href="documentation/?doc=release-validation">Release validation checklist</a></section><section><span class="eyebrow">Operator workflow</span><h2>Four steps from observation to handover</h2><div class="flow"><div><strong>01 · Confirm confidence</strong><small>Source age, completeness and TLS trust</small></div><div><strong>02 · Identify impact</strong><small>PE and PC source context, independent service checks</small></div><div><strong>03 · Follow triage</strong><small>Observed blockers, unknowns and safe next steps</small></div><div><strong>04 · Verify recovery</strong><small>Deployment, prerequisites, service validation and fresh alerts</small></div></div></section><section><h2>What operators can inspect</h2><div class="grid"><article class="card"><h3>Estate and collection</h3><p>Last-known source entries, API response outcomes, authentication groups and explicit gaps. Inventory is not a complete health assessment.</p></article><article class="card"><h3>Prism incidents</h3><p>Source alert lifecycle, events, detailed triage and A200335 deployment/prerequisite evidence. A resolved alert does not establish recovery.</p></article><article class="card"><h3>Evidence and administration</h3><p>Artifacts, hashes, schedule previews, recorded execution, access settings and backup controls with clear boundaries.</p></article></div></section><section><h2>Learn and validate</h2><div class="grid">{cards}</div><p><a href="documentation/">All six PDF guides</a> · <a href="tutorials/">Six guided tutorials and transcripts</a></p></section><section><h2>Privacy by construction</h2><p>Public documentation is generated only from a curated synthetic catalogue. It never imports saved connections, database records, raw evidence, live incident text or lab screenshots. Reserved example names and documentation-only addresses illustrate procedures.</p></section>'''),encoding='utf-8')

(OUT/'documentation'/'index.html').write_text(page('PDF documentation library','''<span class="eyebrow">Versioned operator reference</span><h1>Documentation library</h1><p class="lead">Six source-reviewed guides for evaluation, operations, triage and release acceptance. All examples are synthetic.</p><div class="notice">Candidate documentation is not production acceptance. Validate procedures against your installed software and local change process.</div><label class="search">Search title, audience or content<input id="search" type="search" placeholder="Search recovery, TLS, backups..." autocomplete="off"></label><p id="count" role="status"></p><div class="grid" id="library"></div><section id="selected" hidden></section>''',1,'<script src="library.js"></script>'),encoding='utf-8')
(OUT/'documentation'/'library.js').write_text('''let guides=[]; const root=document.querySelector('#library'),selected=document.querySelector('#selected');
function el(tag,text){const n=document.createElement(tag);n.textContent=text;return n;}
function show(id){const g=guides.find(g=>g.id===id);selected.replaceChildren();selected.hidden=!g;if(!g)return;selected.append(el('h2',g.title),el('p',g.summary));const a=el('a','Download PDF');a.className='button';a.href=g.pdf;a.download=g.pdf.split('/').pop();selected.append(a);const hash=el('p','SHA-256: '+g.sha256);hash.className='hash';selected.append(hash);const link=el('a','Open PDF in a new tab');link.href=g.pdf;link.target='_blank';link.rel='noopener';selected.append(link);for(const section of g.sections){selected.append(el('h3',section.title));const list=el('ol','');for(const step of section.steps)list.append(el('li',step));selected.append(list);}}
function render(){const q=document.querySelector('#search').value.toLowerCase();const found=guides.filter(g=>JSON.stringify(g).toLowerCase().includes(q));root.replaceChildren();for(const g of found){const card=el('article','');card.className='card';card.append(el('h3',g.title),el('p',g.summary),el('p',g.audience));const a=el('a','Read guide / download PDF');a.href='?doc='+encodeURIComponent(g.id);card.append(a);root.append(card);}document.querySelector('#count').textContent=found.length+' of '+guides.length+' guides';}
fetch('library.json').then(r=>{if(!r.ok)throw Error();return r.json()}).then(data=>{guides=data.guides;render();show(new URLSearchParams(location.search).get('doc'));}).catch(()=>{root.textContent='Library unavailable. Reload or use the repository documentation.'});document.querySelector('#search').addEventListener('input',render);
''')
(OUT/'tutorials').mkdir(exist_ok=True)
(OUT/'tutorials'/'index.html').write_text(page('Guided tutorials','''<span class="eyebrow">Synthetic training scenarios</span><h1>Operations tutorials</h1><p class="lead">Six captioned video overviews with step-by-step transcripts and companion PDFs. No production or lab records appear in these exercises.</p><label class="search">Choose tutorial<select id="tutorial"></select></label><video id="video" controls preload="metadata" aria-label="Synthetic captioned tutorial overview"></video><p class="meta">40-second silent, captioned training overview. Read the full procedure below before acting.</p><article class="reader"><p class="meta" id="progress" aria-live="polite"></p><h2 id="title"></h2><h3 id="section-title"></h3><ol id="steps"></ol><div class="steps-nav"><button class="button secondary" id="previous">Previous</button><button class="button" id="next">Next</button><a id="pdf" href="../documentation/">Companion PDF</a></div></article><p>These are synthetic training overviews, not recordings of live changes or verified infrastructure recovery. The full transcript is available in the companion guide.</p>''',1,'<script src="tutorials.js"></script>'),encoding='utf-8')
(OUT/'tutorials'/'tutorials.js').write_text('''let guides=[],index=0,step=0;const select=document.querySelector('#tutorial');function render(){const g=guides[index],s=g.sections[step];const video=document.querySelector('#video');if(video.dataset.guide!==g.id){video.dataset.guide=g.id;video.src='media/'+g.id+'.mp4';video.replaceChildren();const track=document.createElement('track');track.kind='captions';track.srclang='en';track.label='English';track.src='media/'+g.id+'.vtt';track.default=true;video.append(track);}document.querySelector('#title').textContent=g.title;document.querySelector('#section-title').textContent=s.title;document.querySelector('#progress').textContent='Tutorial '+(index+1)+' of '+guides.length+' | Step '+(step+1)+' of '+g.sections.length+' | Synthetic scenario';const list=document.querySelector('#steps');list.replaceChildren();for(const text of s.steps){const li=document.createElement('li');li.textContent=text;list.append(li);}document.querySelector('#previous').disabled=step===0;document.querySelector('#next').disabled=step===g.sections.length-1;document.querySelector('#pdf').href='../documentation/?doc='+g.id;select.value=String(index);const url=new URL(location);url.searchParams.set('part',String(index+1));history.replaceState(null,'',url);}
fetch('../documentation/library.json').then(r=>{if(!r.ok)throw Error();return r.json()}).then(data=>{guides=data.guides;for(const [i,g] of guides.entries()){const o=document.createElement('option');o.value=String(i);o.textContent=(i+1)+'. '+g.title;select.append(o);}const p=Number(new URLSearchParams(location.search).get('part'));index=Number.isInteger(p)&&p>=1&&p<=guides.length?p-1:0;render();}).catch(()=>document.querySelector('#progress').textContent='Tutorial content unavailable. Please reload.');select.addEventListener('change',()=>{index=Number(select.value);step=0;render()});document.querySelector('#previous').addEventListener('click',()=>{step--;render()});document.querySelector('#next').addEventListener('click',()=>{step++;render()});
''')
(OUT/'.nojekyll').write_text('')
print(f'Generated {len(GUIDES)} PDFs, library, tutorials and project landing page for {VERSION}')
